insert into public.stories(id,title,description,published,edition) values ('first-light','The Fragments of Eldoria','One apprentice. Five scattered fragments. A world waiting to be rewritten.',true,2) on conflict(id) do update set title=excluded.title,description=excluded.description,published=excluded.published,edition=excluded.edition;
insert into public.story_chapters(id,story_id,position,title,subtitle,lesson_id,content,published) values ('the-awakening','first-light',1,'The book that answered','The Arcane Academy · Objects & movement commands',1,'[{"id":"arrival","type":"narration","text":"On the morning the last streetlamp goes dark, Aether breaks into the abandoned Wizard Academy. He is looking for a candle. He finds a book that knows his name."},{"id":"eldoria","type":"narration","text":"Once, the Ethereal Core carried magic through all of Eldoria: into its forests, its healing potions, the wards around its villages. The old wizards shaped that power with SpellScript, a language of precise instructions. Then Malachar, the Core’s guardian, tried to make every spell answer to him alone. The Core fractured. Five fragments scattered across the kingdom, and magic began to fail."},{"id":"apprentice","type":"narration","text":"Aether is only an apprentice. He has never lit a lantern without help. But the marks in this book make sense to him—the first person in a generation able to read the original language. Between the pages, five empty shapes glow like windows."},{"id":"sparky-hello","type":"dialogue","speaker":"The spellbook","text":"You can read me. That is a beginning. Power is not the same as understanding, Aether. Start with one clear instruction."},{"id":"first-response","type":"choice","text":"Aether rests a hand on the page. What does he say?","options":[{"id":"careful","label":"One step at a time.","response":"The ink settles into a neat line. “A sensible place to begin,” the book replies."},{"id":"curious","label":"Show me what these symbols can do.","response":"A point of gold lights up across the courtyard. “Then let us make a little light.”"}]},{"id":"first-task","type":"narration","text":"A fragment gleams beyond the cracked courtyard tiles. Aether must move two steps east, turn right, take two steps south, and collect it. The book calls him an object: something with a name and actions. He calls it a rather strange introduction. Either way, the first command is aether.move_forward()."}]'::jsonb,true) on conflict(id) do update set title=excluded.title,subtitle=excluded.subtitle,position=excluded.position,lesson_id=excluded.lesson_id,content=excluded.content,published=excluded.published;
insert into public.story_chapters(id,story_id,position,title,subtitle,lesson_id,content,published) values ('a-little-alchemy','first-light',2,'Something worth keeping','Alchemical Storage · Variables & assignment',2,'[{"id":"laboratory","type":"narration","text":"The first fragment leads Aether into the academy’s alchemy room. Its shelves still smell of rain and burnt sugar. Here, a second fragment is sealed inside a bottle of cloudy glass. The label reads: FOR WHEN THE WORLD NEEDS MENDING."},{"id":"recipe","type":"narration","text":"Aether finds star dew, an empty mana flask, and a recipe written in the same small script as the book. He reaches for the ingredients, then stops. Three drops is not the same as thirty. A name is useful only if he remembers what it holds."},{"id":"keeper","type":"dialogue","speaker":"The spellbook","text":"A variable keeps a value under a name. Give mana_flask the value 100. Give star_dew the value 3. The cauldron cannot follow a recipe you have not prepared."},{"id":"brew","type":"narration","text":"Aether writes the two assignments and calls cauldron.brew_elixir(). If the measures are right, the restoration elixir will clear the glass and release the second fragment. For the first time, the recipe feels less like a secret and more like something he can learn."}]'::jsonb,true) on conflict(id) do update set title=excluded.title,subtitle=excluded.subtitle,position=excluded.position,lesson_id=excluded.lesson_id,content=excluded.content,published=excluded.published;
insert into public.story_chapters(id,story_id,position,title,subtitle,lesson_id,content,published) values ('the-patient-garden','first-light',3,'The patient work of growing','The Repeating Grove · For-loops & iteration',3,'[{"id":"garden","type":"narration","text":"Beyond the academy, the Repeating Grove has fallen silent. Six stone beds line the old path. Nothing grows in them. In the heart of the oldest tree, the third fragment shines behind a cage of roots."},{"id":"repetition","type":"narration","text":"Aether kneels at the first bed and copies the growth spell. At the second, he writes it again. By the third, he has smudged the page and misplaced a bracket. The book gently turns back to the first line."},{"id":"loop","type":"dialogue","speaker":"The spellbook","text":"The task is the same each time. Tell me how many times to repeat it, and which instruction belongs inside the loop. Remember the stopping point. Even a good spell needs an end."},{"id":"bloom","type":"narration","text":"Six repetitions. One grow_flower() inside an indented block. Aether begins to understand why the old wizards wrote so little to accomplish so much. When all six beds bloom, their roots will carry light back to the tree and loosen its grip on the fragment."}]'::jsonb,true) on conflict(id) do update set title=excluded.title,subtitle=excluded.subtitle,position=excluded.position,lesson_id=excluded.lesson_id,content=excluded.content,published=excluded.published;
insert into public.story_chapters(id,story_id,position,title,subtitle,lesson_id,content,published) values ('across-the-quiet','first-light',4,'A way across','The Sky Citadel · Functions & invocation',4,'[{"id":"river","type":"narration","text":"The path ends at open sky. Across a gulf of clouds, the Sky Citadel hangs beneath a pale moon. Its bridge has broken into four missing spans. On the far side waits the fourth fragment, too far to reach and too bright to ignore."},{"id":"library","type":"narration","text":"A weathered inscription describes how to place a starlight tile. Aether could write the instructions again each time. Instead, he gathers them under one name: build_bridge. The book glows approvingly. Nothing else happens."},{"id":"bridge-talk","type":"dialogue","speaker":"The spellbook","text":"You have defined a function. That tells me how the spell works. Now invoke it. A recipe on a shelf does not make supper."},{"id":"build","type":"narration","text":"Aether puts a four-step loop inside build_bridge(), then calls the function by name. A reusable spell: not just an answer for this crossing, but a tool for the next. Beyond the bridge, the citadel’s bell waits to ring again."}]'::jsonb,true) on conflict(id) do update set title=excluded.title,subtitle=excluded.subtitle,position=excluded.position,lesson_id=excluded.lesson_id,content=excluded.content,published=excluded.published;
insert into public.story_chapters(id,story_id,position,title,subtitle,lesson_id,content,published) values ('a-different-path','first-light',5,'The mistake in the stone','The Obsidian Crypt · Debugging & index errors',5,'[{"id":"runes","type":"narration","text":"With four fragments tucked safely into the spellbook, Aether descends into the Obsidian Crypt. The final fragment lies beyond it, in the Chrono Vault. Three numbered runes seal the passage. Malachar has left a spell beside them, almost correct."},{"id":"wrong-number","type":"narration","text":"The first instruction names rune 1. The second names rune 2. The last points to rune 9. Aether searches the wall again. There are only three runes. For a moment he thinks he has failed to understand something grand. Then he notices the simpler truth: the instruction is wrong."},{"id":"decision","type":"dialogue","speaker":"The spellbook","text":"An error is information. Read what it tells you, compare it with the world, and change the part that does not fit. Do not throw away the whole spell."},{"id":"cleanse","type":"narration","text":"Repair the last command so it names rune 3, then purify all three runes. This is debugging: a careful correction, not a louder incantation. Somewhere beneath the stone, the way forward begins to stir."}]'::jsonb,true) on conflict(id) do update set title=excluded.title,subtitle=excluded.subtitle,position=excluded.position,lesson_id=excluded.lesson_id,content=excluded.content,published=excluded.published;
insert into public.story_chapters(id,story_id,position,title,subtitle,lesson_id,content,published) values ('the-sky-door','first-light',6,'What a spell gives back','The Celestial Stargate · Parameters & returns',6,'[{"id":"observatory","type":"narration","text":"The crypt opens into an observatory. Brass rings circle an empty doorway, and the Chrono Vault is visible through it like a reflection in dark water. A dial reads: REQUIRED FLUX — 200. Aether’s flask holds only 100 units of mana."},{"id":"calculation","type":"narration","text":"An old conversion spell can double an input. But the spell must receive a value, calculate a result, and return it. Aether names the parameter mana and writes return mana * 2. He has not made power from nothing; he has translated the flask’s stored mana into the gate’s measure of flux."},{"id":"gate-talk","type":"dialogue","speaker":"The spellbook","text":"A parameter is what a function receives. A return value is what it gives back. Store the result of calculate_flux(100), align the rings, then use that result to charge the gate."},{"id":"gate","type":"narration","text":"The order matters. Aether steadies the brass rings before sending the calculated flux through them. If the conversion is right, the doorway will hold long enough to cross. On the other side, a clock is ticking backwards."}]'::jsonb,true) on conflict(id) do update set title=excluded.title,subtitle=excluded.subtitle,position=excluded.position,lesson_id=excluded.lesson_id,content=excluded.content,published=excluded.published;
insert into public.story_chapters(id,story_id,position,title,subtitle,lesson_id,content,published) values ('pieces-of-time','first-light',7,'The order of things','The Chrono Vault · Lists, indices & sorting',7,'[{"id":"time","type":"narration","text":"Inside the vault, rain rises toward the ceiling. An hourglass fills from below. Four numbered control crystals orbit a sealed chamber in the order 4, 1, 3, 2. Beyond the chamber’s glass rests the fifth and final Core fragment."},{"id":"inventory","type":"narration","text":"These four crystals are the vault’s controls, not pieces of the Core. Their values tell the machine when to act; their indices tell Aether where each sits in the list. The first position is index 0. Position and value, he discovers, are different things."},{"id":"sort","type":"dialogue","speaker":"The spellbook","text":"Keep the crystals together in one list. Sort their values into ascending order, then pass the sorted list to stabilize_vortex. The machine needs the result, not merely the promise that you sorted it."},{"id":"stabilize","type":"narration","text":"Aether writes crystals = [4, 1, 3, 2]. With the controls restored to 1, 2, 3, 4, the vault can release its hold on time—and its final fragment. Five lights will fill the book. One broken Core remains to be mended."}]'::jsonb,true) on conflict(id) do update set title=excluded.title,subtitle=excluded.subtitle,position=excluded.position,lesson_id=excluded.lesson_id,content=excluded.content,published=excluded.published;
insert into public.story_chapters(id,story_id,position,title,subtitle,lesson_id,content,published) values ('first-light-restored','first-light',8,'A light that belongs to everyone','The Ethereal Core · Bringing it all together',8,'[{"id":"chimera","type":"narration","text":"Malachar waits beside the fractured Core. His spell has wrapped it in a lattice of violet light, a hundred points of corruption holding the pieces apart. The five fragments in Aether’s book pull toward their old places."},{"id":"malachar","type":"dialogue","speaker":"Malachar","text":"I could have kept Eldoria safe. One will. One perfect spell. No mistakes."},{"id":"answer","type":"narration","text":"Aether thinks of the smudged page in the grove, the bridge he forgot to invoke, the wrong number on the crypt wall. Every mistake taught him something. A world that can never change can never mend."},{"id":"last-choice","type":"choice","text":"Before he opens the book, what does Aether choose to remember?","options":[{"id":"persistence","label":"A mistake can show us the next step.","response":"Aether turns to the page he once crossed out. This time, he knows why the spell will work."},{"id":"together","label":"Magic belongs to everyone who learns it.","response":"Aether imagines the academy with its doors open, its tables crowded, and enough books for everyone."}]},{"id":"finish","type":"dialogue","speaker":"The spellbook","text":"Protect yourself first: mana_shield = 100. Repeat the starlight bolt three times to weaken the lattice. Then call restore_core() to break the last binding. You have learned every part of this spell."},{"id":"final-task","type":"narration","text":"Aether lifts the book. He is still an apprentice. He is still afraid. But he no longer needs to know everything before he can begin. One clear instruction. Then the next."}]'::jsonb,true) on conflict(id) do update set title=excluded.title,subtitle=excluded.subtitle,position=excluded.position,lesson_id=excluded.lesson_id,content=excluded.content,published=excluded.published;
